use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let cs: Vec<char> = line.chars().collect()
        let n: int = cs.len() as int
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut in_q = false
        let mut i: int = 0
        while i < n {
            let c = cs[i as usize]
            if in_q {
                if c == '"' {
                    if i + 1 < n && cs[(i + 1) as usize] == '"' {
                        cur.push('"')
                        i += 2
                    } else {
                        in_q = false
                        i += 1
                    }
                } else {
                    cur.push(c)
                    i += 1
                }
            } else {
                if c == '"' {
                    in_q = true
                } else if c == ',' {
                    fields.push(cur)
                    cur = ""
                } else {
                    cur.push(c)
                }
                i += 1
            }
        }
        fields.push(cur)
        let mut out = "${fields.len()}: "
        let mut first = true
        for f in fields {
            if !first {
                out.push('|')
            }
            first = false
            out.push_str("[${f}]")
        }
        println(out)
    }
}

